CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id varchar(64) NOT NULL DEFAULT auth.uid(), name varchar(64) NOT NULL, status varchar(16) NOT NULL DEFAULT 'IN_USE', brand varchar(64), model varchar(128), purchase_date date, purchase_price_cents integer, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());